import ast, base64, copy, difflib, hashlib, json, re
SOURCE=base64.b64decode("").decode("utf-8")
BEFORE=base64.b64decode("").decode("utf-8")
def select(source, wanted):
    tree=ast.parse(source)
    compile(tree,"<whole-source-syntax-only>","exec")
    ns={"hashlib":hashlib,"json":json,"re":re}
    nodes=[n for n in tree.body if isinstance(n,ast.Assign) or (isinstance(n,ast.ClassDef) and n.name=="Refused") or (isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name in wanted)]
    exec(compile(ast.Module(body=nodes,type_ignores=[]),"<selected-pure-parser>","exec"),ns)
    return ns,tree
wanted={"timing_object_pairs","timing_integer","timing_noninteger","checked_timing_uint","parse_timing_marker","parse_marker"}
new,tree=select(SOURCE,wanted);old,oldtree=select(BEFORE,{"parse_marker"})
parse=new["parse_marker"];Refused=new["Refused"];U64=(1<<64)-1;U128=(1<<128)-1
pairs=sorted(new["TIMING_PAIRS"])
def bucket(pair=None):
    pair=pair or pairs[0]
    return {"scope":pair[0],"phase":pair[1],"calls":1,"advanced":0,"completed":1,"failed":0,
        "elapsed_us":7,"maximum_elapsed_us":7,"first_entry_remaining_ns":100000,
        "last_exit_remaining_ns":93000,"minimum_entry_remaining_ns":100000,
        "minimum_exit_remaining_ns":93000}
def report(phases=None):
    return {"schema":"heptabao.native-ha.request-failure-timing.v1","request_class":"ordinary",
        "forwarded":False,"status":503,"elapsed_us":10,"entry_remaining_ns":200000,
        "exit_remaining_ns":190000,"bucket_limit":64,"bucket_bound_reached":False,
        "phases":[] if phases is None else phases}
def line(value):
    return b"HBHA-REQUEST-TIMING-FAIL "+json.dumps(value,separators=(",",":")).encode("ascii")+b"\n"
checks=[]
def ok(name,fn):
    fn();checks.append({"case":name,"passed":True})
def accepted(value):
    out=parse(line(value),178)
    assert out["marker"]=="HBHA-REQUEST-TIMING-FAIL" and out["line_number"]==178
    assert out["line_sha256"]==hashlib.sha256(line(value)).hexdigest()
    assert out["status"]==value["status"] and len(out["phases"])==len(value["phases"])
    return out
def refused_raw(raw):
    try:parse(raw,178)
    except Refused as error:
        assert len(error.args)==1 and re.fullmatch("[a-z0-9_]+",error.args[0])
        assert "synthetic_secret" not in str(error)
        return
    raise AssertionError("accepted invalid marker")
def invalid(change):
    value=report([bucket()]);change(value);refused_raw(line(value))
