 b"HBHA-NATIVE-SYNC-FAIL step=committed_read_index code=read_index_refused reason_sha=" + b"a"*64 + b" elapsed_us=249842 step_elapsed_us=249835 original_deadline_expired=true original_remaining_ns=0 panicking=false\n",
